<script setup>
import { ref } from 'vue'; import { api } from '../api'; const code=ref('WMS|DELIVERY|DEL-1001|PICKUP|v1'),result=ref(null),tag=ref('E2000017221101441890ABCD'); async function scan(){try{result.value=(await api.post('/scans',{code:code.value,method:'QR'})).data}catch(e){result.value=e.response?.data}}async function rfid(){result.value=(await api.post('/rfid/events',{tagId:tag.value,readerId:'WEB-DEMO-READER',action:'SEEN'})).data}
</script>
<template><div class="split"><div class="card modal-card"><h3 style="margin-top:0">QR process scanner</h3><p style="font-size:12px;color:#64748b">Paste or scan a WMS QR payload. The backend changes the workflow state and writes a process event.</p><div class="field"><label>QR payload</label><input v-model="code"/></div><button class="btn" style="margin-top:12px" @click="scan">Process QR</button></div><div class="card modal-card"><h3 style="margin-top:0">RFID event gateway</h3><p style="font-size:12px;color:#64748b">RFID readers can POST tag events into the same paperless event stream.</p><div class="field"><label>RFID tag EPC</label><input v-model="tag"/></div><button class="btn dark" style="margin-top:12px" @click="rfid">Simulate RFID read</button></div></div><div v-if="result" class="card section modal-card"><h3>Result</h3><div class="code">{{JSON.stringify(result,null,2)}}</div></div></template>
